package merge

import (
	"reflect"
	"testing"
)

func TestGSRWitness(t *testing.T) {
	got := Merge(StaticLister{Names: []string{"b", "a"}}, StaticLister{Names: []string{"c"}})
	want := []string{"a", "b", "c"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("Merge = %v, want %v", got, want)
	}
}
